--  DDL for View AR_SOURCE_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE VIEW "ERP"."AR_SOURCE_VIEW" ("DOC_TYPE", "DOC_ID", "DOC_DATE", "DOC_NO", "CUST_ID", "AMOUNT", "AR_ID", "SIGN", "CREATE_INVOICE") AS
  SELECT
'SALES' DOC_TYPE,
SALES_ID DOC_ID,
POST_DATE DOC_DATE,
INVOICE_NO DOC_NO,
CUST_ID,
SALES_AMOUNT AMOUNT,
NULL AR_ID,
+1 SIGN,
'Y' CREATE_INVOICE
FROM SALES_HD
--------------------------------------------------------
--  DDL for View GL_SOURCE_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE VIEW "ERP"."GL_SOURCE_VIEW" ("DOC_TYPE", "DOC_ID", "LINE_ID", "AMOUNT_SOURCE", "AMOUNT") AS
  SELECT
'SALES'        AS DOC_TYPE,
H.SALES_ID     AS DOC_ID,
NULL           AS LINE_ID,
'SALES_AMOUNT' AS AMOUNT_SOURCE,
H.SALES_AMOUNT AS AMOUNT
FROM SALES_HD H
UNION ALL
-- ========================
-- SALES COGS (LINE LEVEL)
-- ========================
SELECT
'SALES',
L.SALES_ID,
L.LINE_ID,
'COGS',
(L.BASE_QTY * L.UNIT_COST) AS AMOUNT
FROM SALES_LINE L
--------------------------------------------------------
--  DDL for View INVENTORY_SOURCE_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE VIEW "ERP"."INVENTORY_SOURCE_VIEW" ("SOURCE_MODULE", "SOURCE_ID", "SOURCE_LINE_ID", "TRANS_DATE", "WH_ID", "ITEM_ID", "UOM_ID", "QTY", "BASE_QTY", "UNIT_COST", "DIRECTION", "AMOUNT") AS
  SELECT
'SALES'            AS SOURCE_MODULE,
H.SALES_ID         AS SOURCE_ID,
L.LINE_ID    	   AS SOURCE_LINE_ID,
H.SALES_DATE       AS TRANS_DATE,
L.WH_ID,
L.ITEM_ID,
L.UOM_ID,
L.QTY,
L.BASE_QTY,
L.UNIT_COST,
'OUT'               AS DIRECTION ,
L.BASE_QTY*L.UNIT_COST AS AMOUNT
FROM SALES_HD H
JOIN SALES_LINE L ON H.SALES_ID = L.SALES_ID
