-- --------------------------------------------------------
-- --  DDL for Procedure SP_COMPUTE_TAX
-- --------------------------------------------------------
-- set define off;

--   CREATE OR REPLACE PROCEDURE "ERP"."SP_COMPUTE_TAX" (
--     P_BASE_TAX        IN NUMBER,
--     P_TAX_GROUP_ID    IN NUMBER,
-- 	P_TAX_AMT		  OUT NUMBER,
-- 	P_EWT_AMT		  OUT NUMBER
-- )
--     IS
-- 	  CURSOR C_TAX IS
-- 	  SELECT
--             TC.TAX_CODE_ID,
--             TC.TAX_CODE,
--             TT.TAX_TYPE_CODE,
--             TC.TAX_RATE,
--             TC.TAX_BEHAVIOR,
--             TGL.SEQ_NO
--         FROM TAX_GROUP_LINE TGL
--             JOIN TAX_CODE TC
--                 ON TGL.TAX_CODE_ID = TC.TAX_CODE_ID
--             JOIN TAX_TYPE TT
--                 ON TC.TAX_TYPE_ID = TT.TAX_TYPE_ID
--         WHERE TGL.TAX_GROUP_ID = P_TAX_GROUP_ID
--         AND TC.ACTIVE_YN = 'Y'
--         ORDER BY TGL.SEQ_NO;
--     ------------------------------------------------------------
--     -- VARIABLES
--     ------------------------------------------------------------
--     V_TAX_AMOUNT           NUMBER;
--     V_TAXABLE_AMOUNT       NUMBER;
--     V_TOTAL_NET            NUMBER := 0;
--     V_TOTAL_VAT            NUMBER := 0;
--     V_TOTAL_EWT            NUMBER := 0;
--     V_TOTAL_FINAL          NUMBER := 0;

-- BEGIN
--     FOR T IN C_TAX LOOP
--             V_TAX_AMOUNT := 0;
--             ----------------------------------------------------
--             -- VAT COMPUTATION
--             ----------------------------------------------------
--             IF T.TAX_TYPE_CODE = 'VAT' THEN
--                 ------------------------------------------------
--                 -- VAT EXCLUSIVE
--                 ------------------------------------------------
--                 IF T.TAX_BEHAVIOR = 'ADD_ON' THEN
--                     V_TAX_AMOUNT := ROUND(
--                         P_BASE_TAX  *
--                         (T.TAX_RATE / 100),
--                         2
--                     );
--                 ------------------------------------------------
--                 -- VAT INCLUSIVE
--                 ------------------------------------------------
--                 ELSIF T.TAX_BEHAVIOR = 'INCLUSIVE' THEN
--                     V_TAX_AMOUNT := ROUND(
--                         P_BASE_TAX  -
--                         (
--                             V_TAXABLE_AMOUNT /
--                             (1 + (T.TAX_RATE / 100))
--                         ),
--                         2
--                     );
--                 END IF;
--                 V_TOTAL_VAT :=
--                     V_TOTAL_VAT + V_TAX_AMOUNT;
--             ----------------------------------------------------
--             -- EWT
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'EWT' THEN
--                 V_TAX_AMOUNT := ROUND(
--                     P_BASE_TAX  *
--                     (T.TAX_RATE / 100),
--                     2
--                 );
--                 V_TOTAL_EWT :=
--                     V_TOTAL_EWT + V_TAX_AMOUNT;
--             ----------------------------------------------------
--             -- FINAL TAX
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'FINAL' THEN
--                 V_TAX_AMOUNT := ROUND(
--                     P_BASE_TAX  *
--                     (T.TAX_RATE / 100),
--                     2
--                 );
--                 V_TOTAL_FINAL :=
--                     V_TOTAL_FINAL + V_TAX_AMOUNT;
--             ----------------------------------------------------
--             -- PERCENTAGE TAX
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'PERCENT' THEN
--                 V_TAX_AMOUNT := ROUND(
--                     P_BASE_TAX  *
--                     (T.TAX_RATE / 100),
--                     2
--                 );
--             END IF;
--         END LOOP;
--         -- ? RETURN VALUES TO OUT PARAMETERS
--        P_TAX_AMT  := V_TOTAL_VAT ;
--        P_EWT_AMT  := V_TOTAL_EWT ;
-- END;
-- --------------------------------------------------------
-- --  DDL for Procedure SP_COMPUTE_TAX1
-- --------------------------------------------------------
-- set define off;

--   CREATE OR REPLACE PROCEDURE "ERP"."SP_COMPUTE_TAX1" (
--     P_MODULE_CODE     IN VARCHAR2,
--     P_DOC_ID          IN NUMBER
-- )
-- IS

--     ------------------------------------------------------------
--     -- DOCUMENT LINES
--     ------------------------------------------------------------
--     CURSOR C_LINES IS

--         SELECT
--             LINE_ID,
--             TAX_GROUP_ID,
--             LINE_AMOUNT
--         FROM (
--             ----------------------------------------------------
--             -- SALES
--             ----------------------------------------------------
--             SELECT
--                 D.LINE_ID,
--                 D.TAX_GROUP_ID,
--                 D.LINE_AMOUNT
--             FROM SALES_INVOICE_D D
--             WHERE P_MODULE_CODE = 'SALES'
--             AND D.SALES_ID = P_DOC_ID

--             UNION ALL

--             ----------------------------------------------------
--             -- PURCHASE
--             ----------------------------------------------------
--             SELECT
--                 D.LINE_ID,
--                 D.TAX_GROUP_ID,
--                 D.LINE_AMOUNT
--             FROM PURCHASE_D D
--             WHERE P_MODULE_CODE = 'PURCHASE'
--             AND D.PURCHASE_ID = P_DOC_ID
--         );

--     ------------------------------------------------------------
--     -- TAX GROUP DETAILS
--     ------------------------------------------------------------
--     CURSOR C_TAX (
--         P_TAX_GROUP_ID NUMBER
--     ) IS
--         SELECT
--             TC.TAX_CODE_ID,
--             TC.TAX_CODE,
--             TT.TAX_TYPE_CODE,
--             TC.TAX_RATE,
--             TC.VAT_CLASS,
--             TC.TAX_BEHAVIOR,
--             TC.BIR_ATC_CODE,
--             TGL.SEQ_NO
--         FROM TAX_GROUP_LINE TGL
--              JOIN TAX_CODE TC
--                 ON TGL.TAX_CODE_ID = TC.TAX_CODE_ID
--              JOIN TAX_TYPE TT
--                 ON TC.TAX_TYPE_ID = TT.TAX_TYPE_ID
--         WHERE TGL.TAX_GROUP_ID = P_TAX_GROUP_ID
--         AND TC.ACTIVE_YN = 'Y'
--         ORDER BY TGL.SEQ_NO;

--     ------------------------------------------------------------
--     -- VARIABLES
--     ------------------------------------------------------------
--     V_TAX_AMOUNT           NUMBER;
--     V_TAXABLE_AMOUNT       NUMBER;

--     V_TOTAL_NET            NUMBER := 0;
--     V_TOTAL_VAT            NUMBER := 0;
--     V_TOTAL_EWT            NUMBER := 0;
--     V_TOTAL_FINAL          NUMBER := 0;

-- BEGIN

--     ------------------------------------------------------------
--     -- DELETE OLD TAX TRANSACTIONS
--     ------------------------------------------------------------
--     DELETE FROM TAX_TRANSACTION
--     WHERE MODULE_CODE = P_MODULE_CODE
--     AND DOC_ID = P_DOC_ID;

--     ------------------------------------------------------------
--     -- LOOP DOCUMENT LINES
--     ------------------------------------------------------------
--     FOR R IN C_LINES LOOP

--         V_TAXABLE_AMOUNT := R.LINE_AMOUNT;

--         --------------------------------------------------------
--         -- LOOP TAX GROUP
--         --------------------------------------------------------
--         FOR T IN C_TAX(R.TAX_GROUP_ID) LOOP

--             V_TAX_AMOUNT := 0;

--             ----------------------------------------------------
--             -- VAT COMPUTATION
--             ----------------------------------------------------
--             IF T.TAX_TYPE_CODE = 'VAT' THEN

--                 ------------------------------------------------
--                 -- VAT EXCLUSIVE
--                 ------------------------------------------------
--                 IF T.TAX_BEHAVIOR = 'ADD_ON' THEN

--                     V_TAX_AMOUNT := ROUND(
--                         V_TAXABLE_AMOUNT *
--                         (T.TAX_RATE / 100),
--                         2
--                     );

--                 ------------------------------------------------
--                 -- VAT INCLUSIVE
--                 ------------------------------------------------
--                 ELSIF T.TAX_BEHAVIOR = 'INCLUSIVE' THEN

--                     V_TAX_AMOUNT := ROUND(
--                         V_TAXABLE_AMOUNT -
--                         (
--                             V_TAXABLE_AMOUNT /
--                             (1 + (T.TAX_RATE / 100))
--                         ),
--                         2
--                     );

--                 END IF;

--                 V_TOTAL_VAT :=
--                     V_TOTAL_VAT + V_TAX_AMOUNT;

--             ----------------------------------------------------
--             -- EWT
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'EWT' THEN

--                 V_TAX_AMOUNT := ROUND(
--                     V_TAXABLE_AMOUNT *
--                     (T.TAX_RATE / 100),
--                     2
--                 );

--                 V_TOTAL_EWT :=
--                     V_TOTAL_EWT + V_TAX_AMOUNT;

--             ----------------------------------------------------
--             -- FINAL TAX
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'FINAL' THEN

--                 V_TAX_AMOUNT := ROUND(
--                     V_TAXABLE_AMOUNT *
--                     (T.TAX_RATE / 100),
--                     2
--                 );

--                 V_TOTAL_FINAL :=
--                     V_TOTAL_FINAL + V_TAX_AMOUNT;

--             ----------------------------------------------------
--             -- PERCENTAGE TAX
--             ----------------------------------------------------
--             ELSIF T.TAX_TYPE_CODE = 'PERCENT' THEN

--                 V_TAX_AMOUNT := ROUND(
--                     V_TAXABLE_AMOUNT *
--                     (T.TAX_RATE / 100),
--                     2
--                 );

--             END IF;

--             ----------------------------------------------------
--             -- SAVE TAX TRANSACTION
--             ----------------------------------------------------
--             INSERT INTO TAX_TRANSACTION (
--                 TAX_TRANS_ID,
--                 MODULE_CODE,
--                 DOC_ID,
--                 LINE_ID,

--                 TAX_CODE_ID,

--                 TAXABLE_AMOUNT,
--                 TAX_RATE,
--                 TAX_AMOUNT,

--                 INPUT_OUTPUT_FLAG,

--                 BIR_ATC_CODE,

--                 CREATED_DATE
--             )
--             VALUES (
--                 SEQ_TAX_TRANS.NEXTVAL,

--                 P_MODULE_CODE,

--                 P_DOC_ID,
--                 R.LINE_ID,

--                 T.TAX_CODE_ID,

--                 V_TAXABLE_AMOUNT,
--                 T.TAX_RATE,
--                 V_TAX_AMOUNT,

--                 CASE
--                     WHEN P_MODULE_CODE = 'SALES'
--                     AND T.TAX_TYPE_CODE = 'VAT'
--                     THEN 'OUTPUT'

--                     WHEN P_MODULE_CODE = 'PURCHASE'
--                     AND T.TAX_TYPE_CODE = 'VAT'
--                     THEN 'INPUT'

--                     ELSE NULL
--                 END,

--                 T.BIR_ATC_CODE,

--                 SYSDATE
--             );

--         END LOOP;

--         V_TOTAL_NET :=
--             V_TOTAL_NET + V_TAXABLE_AMOUNT;

--     END LOOP;

--     ------------------------------------------------------------
--     -- UPDATE DOCUMENT HEADER TOTALS
--     ------------------------------------------------------------

--     ------------------------------------------------------------
--     -- SALES
--     ------------------------------------------------------------
--     IF P_MODULE_CODE = 'SALES' THEN

--         UPDATE SALES_INVOICE_H
--         SET NET_AMOUNT = V_TOTAL_NET,
--             VAT_AMOUNT = V_TOTAL_VAT,
--             EWT_AMOUNT = V_TOTAL_EWT,
--             TOTAL_AMOUNT =
--                 (V_TOTAL_NET + V_TOTAL_VAT)
--                 - V_TOTAL_EWT
--         WHERE SALES_ID = P_DOC_ID;

--     ------------------------------------------------------------
--     -- PURCHASE
--     ------------------------------------------------------------
--     ELSIF P_MODULE_CODE = 'PURCHASE' THEN

--         UPDATE PURCHASE_H
--         SET GROSS_AMOUNT = V_TOTAL_NET,
--             VAT_AMOUNT = V_TOTAL_VAT,
--             EWT_AMOUNT = V_TOTAL_EWT,
--             NET_PAYABLE =
--                 (V_TOTAL_NET + V_TOTAL_VAT)
--                 - V_TOTAL_EWT
--         WHERE PURCHASE_ID = P_DOC_ID;

--     END IF;

-- END;
